// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: montserratFamily } = loadMontserrat();



export type FunnelInfographicProps = Record<string, any>;

// --- Helper Icons ---
const ArrowDown = ({ size, color }: { size: number; color: string }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth="3"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <line x1="12" y1="4" x2="12" y2="20" />
    <polyline points="19 13 12 20 5 13" />
  </svg>
);

const PersonIcon = ({ size, color }: { size: number; color: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={color}>
    <circle cx="12" cy="7" r="4" />
    <path d="M4 21 C4 16 8 13 12 13 C16 13 20 21 Z" />
  </svg>
);

const DollarSignIcon = ({ size, color }: { size: number; color: string }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <line x1="12" y1="1" x2="12" y2="23"></line>
    <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path>
  </svg>
);

const ShoppingBagIcon = ({ size, color }: { size: number; color: string }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"></path>
    <line x1="3" y1="6" x2="21" y2="6"></line>
    <path d="M16 10a4 4 0 0 1-8 0"></path>
  </svg>
);

const FunnelInfographic: React.FC<FunnelInfographicProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  topFunnelColor = "#0f766e",
  fadedFunnelColor = "#e5e7eb",
  accentColor = "#f97316",
  textColor = "#ffffff",
  audienceColor = "#9ca3af",
  topFunnelText = "TOP OF FUNNEL",
  midFunnelText = "MIDDLE OF FUNNEL",
  bottomFunnelText = "BOTTOM OF FUNNEL",
  targetAudienceText = "TARGET AUDIENCE — READY TO BUY",
  particleCount = 50,
  midFunnelTextColor = "#9ca3af",
  bottomFunnelTextColor = "#9ca3af",
  targetAudienceTextColor = "#9ca3af",
  topFunnelTextSize = 48,
  midFunnelTextSize = 35,
  bottomFunnelTextSize = 29,
  targetAudienceTextSize = 42,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants (Scaled down for more border)
  const cx = width / 2;
  const topY1 = height * 0.2;
  const topY2 = height * 0.35;
  const topW1 = width * 0.45;
  const topW2 = width * 0.32;

  const breakGap = height * 0.06;

  const midY1 = topY2 + breakGap;
  const midY2 = midY1 + height * 0.12;
  const midW1 = width * 0.32;
  const midW2 = width * 0.22;

  const botY1 = midY2 + height * 0.02;
  const botY2 = botY1 + height * 0.12;
  const botW1 = width * 0.22;
  const botW2 = width * 0.14;

  // Moved up slightly relative to the bottom to ensure full visibility of text
  const audienceY = botY2 + height * 0.06;

  // Animations
  const buildTop = spring({ frame, fps, config: { damping: 12 } });
  const buildMid = spring({ frame: frame - 15, fps, config: { damping: 12 } });
  const buildBot = spring({ frame: frame - 30, fps, config: { damping: 12 } });
  const buildAudience = spring({ frame: frame - 60, fps, config: { damping: 14 } });
  const spillStartFrame = 45;

  // Pre-calculate inputs (Paid Ads)
  const inputs = React.useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => ({
      xOff: random(`ix-${i}`) * topW1 - topW1 / 2,
      delay: random(`id-${i}`) * 60,
      duration: 50 + random(`idur-${i}`) * 40,
      isArrow: random(`itype-${i}`) > 0.5,
      scale: 0.6 + random(`iscale-${i}`) * 0.6,
    }));
  }, [particleCount, topW1]);

  // Pre-calculate spills (Lost Flow)
  const spills = React.useMemo(() => {
    return new Array(particleCount * 2).fill(0).map((_, i) => {
      const isLeft = random(`dir-${i}`) > 0.5;
      const startX = isLeft
        ? cx - topW2 / 2 + random(`sx-${i}`) * (width * 0.06)
        : cx + topW2 / 2 - random(`sx-${i}`) * (width * 0.06);
      return {
        isLeft,
        startX,
        delay: spillStartFrame + random(`ld-${i}`) * 120,
        duration: 40 + random(`ldur-${i}`) * 30,
        xDist: width * 0.1 + random(`xdist-${i}`) * (width * 0.1),
        yDist: height * 0.2 + random(`ydist-${i}`) * (height * 0.15),
        isArrow: random(`stype-${i}`) > 0.5,
      };
    });
  }, [particleCount, cx, topW2, spillStartFrame, width, height]);

  // Pre-calculate Audience Group (Bottom targets)
  const audienceGroup = React.useMemo(() => {
    return new Array(7).fill(0).map((_, i) => ({
      xOff: (i - 3) * (width * 0.05) + random(`ax-${i}`) * 15,
      yOff: random(`ay-${i}`) * 15 - 7.5,
    }));
  }, [width]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: montserratFamily, transition: "none" }}>
      
      {/* DYNAMIC GRID BACKGROUND */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <defs>
          <pattern
            id="dynamicGrid"
            width="60"
            height="60"
            patternUnits="userSpaceOnUse"
            patternTransform={`translate(${frame * 0.4}, ${frame * 0.4})`}
          >
            <path
              d="M 60 0 L 0 0 0 60"
              fill="none"
              stroke={audienceColor}
              strokeWidth="1.5"
              opacity="0.15"
            />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#dynamicGrid)" />
      </svg>

      {/* SCALED CONTAINER TO ALLOW ROOM FOR CAMERA ZOOM */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          transform: "scale(0.65)",
          transformOrigin: "center",
          transition: "none",
        }}
      >
        {/* INPUT PARTICLES (POURING IN) */}
        {inputs.map((p, i) => {
          const localFrame = Math.max(0, frame - p.delay);
          const cycle = localFrame % p.duration;
          const progress = cycle / p.duration;
          const y = interpolate(progress, [0, 1], [-height * 0.05, topY1 + height * 0.08]);
          const opacity = interpolate(progress, [0, 0.1, 0.8, 1], [0, 1, 1, 0]);
          const rot = interpolate(progress, [0, 1], [0, 15]);

          return (
            <div
              key={`in-${i}`}
              style={{
                position: "absolute",
                left: cx + p.xOff,
                top: y,
                opacity: frame < p.delay ? 0 : opacity,
                transform: `translate(-50%, -50%) scale(${p.scale}) rotate(${rot}deg)`,
                transition: "none",
              }}
            >
              {p.isArrow ? (
                <ArrowDown size={width * 0.02} color={accentColor} />
              ) : (
                <PersonIcon size={width * 0.018} color={accentColor} />
              )}
            </div>
          );
        })}

        {/* FUNNEL GEOMETRY */}
        <svg
          style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible", transition: "none" }}
        >
          <defs>
            <linearGradient id="topGradient" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor={topFunnelColor} />
              <stop offset="100%" stopColor={topFunnelColor} stopOpacity={0.8} />
            </linearGradient>
            <linearGradient id="fadedGradient" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor={fadedFunnelColor} />
              <stop offset="100%" stopColor={fadedFunnelColor} stopOpacity={0.6} />
            </linearGradient>
          </defs>

          {/* Top Band */}
          <polygon
            points={`${cx - topW1 / 2},${topY1} ${cx + topW1 / 2},${topY1} ${cx + topW2 / 2},${topY2} ${cx - topW2 / 2},${topY2}`}
            fill="url(#topGradient)"
            style={{
              transformOrigin: `${cx}px ${topY1}px`,
              transform: `scaleY(${buildTop})`,
              transition: "none",
            }}
          />

          {/* Middle Band (Faded) */}
          <polygon
            points={`${cx - midW1 / 2},${midY1} ${cx + midW1 / 2},${midY1} ${cx + midW2 / 2},${midY2} ${cx - midW2 / 2},${midY2}`}
            fill="url(#fadedGradient)"
            style={{
              transformOrigin: `${cx}px ${midY1}px`,
              transform: `scaleY(${buildMid})`,
              transition: "none",
            }}
          />

          {/* Bottom Band (Faded) */}
          <polygon
            points={`${cx - botW1 / 2},${botY1} ${cx + botW1 / 2},${botY1} ${cx + botW2 / 2},${botY2} ${cx - botW2 / 2},${botY2}`}
            fill="url(#fadedGradient)"
            style={{
              transformOrigin: `${cx}px ${botY1}px`,
              transform: `scaleY(${buildBot})`,
              transition: "none",
            }}
          />
        </svg>

        {/* FUNNEL LABELS */}
        <div
          style={{
            position: "absolute",
            top: topY1 + (topY2 - topY1) / 2,
            left: cx,
            transform: `translate(-50%, -50%) scale(${buildTop})`,
            fontSize: topFunnelTextSize * (width / 1920),
            fontWeight: 800,
            color: textColor,
            letterSpacing: "0.1em",
            textAlign: "center",
            width: topW2,
            transition: "none",
          }}
        >
          {topFunnelText}
        </div>

        <div
          style={{
            position: "absolute",
            top: midY1 + (midY2 - midY1) / 2,
            left: cx,
            transform: `translate(-50%, -50%) scale(${buildMid})`,
            fontSize: midFunnelTextSize * (width / 1920),
            fontWeight: 700,
            color: midFunnelTextColor,
            letterSpacing: "0.05em",
            textAlign: "center",
            width: midW2,
            transition: "none",
          }}
        >
          {midFunnelText}
        </div>

        <div
          style={{
            position: "absolute",
            top: botY1 + (botY2 - botY1) / 2,
            left: cx,
            transform: `translate(-50%, -50%) scale(${buildBot})`,
            fontSize: bottomFunnelTextSize * (width / 1920),
            fontWeight: 700,
            color: bottomFunnelTextColor,
            letterSpacing: "0.05em",
            textAlign: "center",
            width: botW2,
            transition: "none",
          }}
        >
          {bottomFunnelText}
        </div>

        {/* SPILL PARTICLES (THE LEAK) */}
        {spills.map((p, i) => {
          if (frame < p.delay) return null;
          const localFrame = frame - p.delay;
          const cycle = localFrame % p.duration;
          const progress = cycle / p.duration;

          const endX = p.isLeft ? p.startX - p.xDist : p.startX + p.xDist;
          const x = interpolate(progress, [0, 1], [p.startX, endX], {
            easing: Easing.out(Easing.quad),
          });
          
          const startY = topY2 + height * 0.02;
          const endY = startY + p.yDist;
          const y = interpolate(progress, [0, 1], [startY, endY], {
            easing: Easing.in(Easing.quad),
          });
          
          const opacity = interpolate(progress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]);
          const rot = interpolate(progress, [0, 1], [0, p.isLeft ? -180 : 180]);

          return (
            <div
              key={`spill-${i}`}
              style={{
                position: "absolute",
                left: x,
                top: y,
                opacity,
                transform: `translate(-50%, -50%) rotate(${rot}deg) scale(0.6)`,
                transition: "none",
              }}
            >
              {p.isArrow ? (
                <ArrowDown size={width * 0.02} color={accentColor} />
              ) : (
                <PersonIcon size={width * 0.018} color={accentColor} />
              )}
            </div>
          );
        })}

        {/* TARGET AUDIENCE */}
        <div
          style={{
            position: "absolute",
            top: audienceY,
            left: cx,
            transform: `translate(-50%, 0) scale(${buildAudience})`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: `${height * 0.02}px`,
            transition: "none",
          }}
        >
          <div style={{ position: "relative", width: width * 0.45, height: height * 0.08 }}>
            {audienceGroup.map((person, i) => (
              <div
                key={`aud-${i}`}
                style={{
                  position: "absolute",
                  left: (width * 0.45) / 2 + person.xOff,
                  top: height * 0.02 + person.yOff,
                  transform: "translate(-50%, -50%)",
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "flex-end",
                  transition: "none",
                }}
              >
                {i % 2 === 0 ? (
                  <DollarSignIcon size={width * 0.035} color={audienceColor} />
                ) : (
                  <ShoppingBagIcon size={width * 0.035} color={audienceColor} />
                )}
              </div>
            ))}
          </div>
          <div
            style={{
              fontSize: targetAudienceTextSize * (width / 1920),
              fontWeight: 800,
              color: targetAudienceTextColor,
              letterSpacing: "0.05em",
              marginTop: `${height * 0.01}px`,
              textAlign: "center",
            }}
          >
            {targetAudienceText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FunnelInfographic;